import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { PrismaClient } from '@prisma/client';
import { chromium } from './browser.mjs';
const current = JSON.parse(fs.readFileSync('tests/.runtime/client-audit-current.json'));
const fixture = JSON.parse(fs.readFileSync(current.fixture));
assert(fixture.base === 'http://127.0.0.1:3212', 'Audit must target isolated server');
// Preserve the 127.0.0.1 setup-origin failure; use the working hostname for remaining UI coverage.
fixture.base = 'http://localhost:3212';
const only = process.env.AUDIT_CASES?.split(',');
const enabled = id => !only || only.includes(id);
const out = path.resolve('test-artifacts/client-audit');
fs.mkdirSync(out, { recursive: true });
const stateFile = path.join(fixture.runtime, 'browser-state.json');
const dataFile = path.join(fixture.runtime, 'browser-data.json');
const resultsFile = path.join(out, 'browser-results.json');
const results = fs.existsSync(resultsFile) ? JSON.parse(fs.readFileSync(resultsFile)) : [];
const data = fs.existsSync(dataFile) ? JSON.parse(fs.readFileSync(dataFile)) : {};
const db = new PrismaClient({ datasources: { db: { url: fixture.database } } });
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ baseURL: fixture.base, viewport: { width: 1440, height: 900 }, ...(fs.existsSync(stateFile) ? { storageState: stateFile } : {}), recordVideo: { dir: path.join(out, 'videos'), size: { width: 1440, height: 900 } } });
const captured = new Map();
// Read the real server response before navigation removes its Chromium body; no responses are mocked.
await context.route('**/api/**', async route => { const r = await route.fetch(); const body = await r.body(); try { captured.set(route.request().url(), JSON.parse(body.toString())); } catch {} await route.fulfill({ response:r, body }); });
const page = await context.newPage();
page.setDefaultTimeout(8000);
const errors = []; const badRequests = [];
page.on('pageerror', e => errors.push({ url: page.url(), message: e.message }));
page.on('console', m => { if (m.type() === 'error') errors.push({ url: page.url(), message: m.text() }); });
page.on('response', r => { if (r.status() >= 400) badRequests.push({ url: r.url(), status: r.status() }); });
function save() { fs.writeFileSync(resultsFile, JSON.stringify(results, null, 2)); fs.writeFileSync(dataFile, JSON.stringify(data, null, 2)); fs.writeFileSync(path.join(out, 'browser-errors.json'), JSON.stringify({ errors, badRequests }, null, 2)); }
async function shot(name) { const file = `${name.replace(/[^a-z0-9-]/gi, '-').slice(0,90)}.png`; await page.screenshot({ path: path.join(out, file), fullPage: true }); return `test-artifacts/client-audit/${file}`; }
async function test(id, name, fn) {
  if (!enabled(id) || results.some(r => r.id === id && r.status === 'PASS')) return;
  const start = Date.now(); const before = errors.length; const requests = badRequests.length;
  try { const notes = await fn(); results.push({ id, name, status: 'PASS', method: 'Chromium UI', durationMs: Date.now() - start, notes: notes ?? '', screenshot: await shot(id), errors: errors.slice(before), failedRequests: badRequests.slice(requests) }); console.log(`PASS ${id} ${name}`); }
  catch (e) { let screenshot; try { screenshot = await shot(`${id}-FAILED`); } catch {} results.push({ id, name, status: 'FAIL', method: 'Chromium UI', durationMs: Date.now() - start, error: e.message, screenshot, errors: errors.slice(before), failedRequests: badRequests.slice(requests) }); console.log(`FAIL ${id} ${name}: ${e.message.slice(0,400)}`); }
  save();
}
function gap(id, name, notes, status = 'NOT IMPLEMENTED') { if (!enabled(id) || results.some(r=>r.id===id)) return; results.push({ id, name, status, method: 'UI + source inventory', notes }); save(); console.log(`${status} ${id} ${name}`); }
const btn = (name, root = page) => root.getByRole('button', { name, exact: true });
const label = (name, root = page) => { const exact = new RegExp('^' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$'); return root.locator('label.field').filter({has:page.locator('.field-label').filter({hasText:exact})}).locator('input,select,textarea').or(root.locator(`[aria-label="${name}"]`)); };
const form = () => page.locator('form').last();
async function visible(text, root = page) { await root.getByText(text, { exact: false }).first().waitFor({ state: 'visible' }); }
async function go(url) { const response = await page.goto(url); assert(response?.status() < 400, `Page ${url}: HTTP ${response?.status()}`); await page.locator('main').waitFor(); }
async function click(name, root) { await btn(name, root).click(); }
async function submit(name, endpoint, root = page) { const response = page.waitForResponse(r => r.url().endsWith(endpoint) && r.request().method() === 'POST').then(async r=>({ok:r.ok(),status:r.status(),body:captured.get(r.url()) ?? await r.json()})).catch(error=>({error})); await click(name, root); const r = await response; if(r.error) throw r.error; assert(r.ok, `HTTP ${r.status}: ${JSON.stringify(r.body)}`); return r.body; }
async function select(name, text, root = page) { await label(name, root).selectOption({ label: text }); }
async function login(email = fixture.ownerEmail, password = fixture.password, target = page) { await target.goto('/login'); if (target.url().endsWith('/dashboard')) return; await target.getByLabel('Work email', { exact: true }).fill(email); await target.getByLabel('Password', { exact: true }).fill(password); await target.getByRole('button', { name: 'Sign in to workspace', exact: true }).click(); await target.waitForURL('**/dashboard'); }
async function customer(name, phone, type = 'Individual') { await go('/customers'); await click('New customer'); const d = page.getByRole('dialog'); await label('Full name *', d).fill(name); await label('Phone *', d).fill(phone); await label('Email', d).fill(`${name.startsWith('AUDIT Alice')?'alice':'bob'}@audit.test`); await label('City', d).fill('Pune'); await select('Customer type', type, d); const r = await submit('Create customer', '/api/customers', d); await page.waitForURL('**/customers/' + r.id); return r; }
async function booking({ pnr = '', price = '1000.10', deadline = '2' } = {}) { await go(`/ticketing/new?customer=${data.alice.id}`); await label('Fare (INR)').fill(price); await label('Route / sector').fill('BOM → DXB'); await label('Airline').fill('Audit Airlines'); if (pnr) { await label('Actual PNR (optional)').fill(pnr); await label('Ticketing deadline (hours from now)').fill(deadline); } await page.getByRole('checkbox', { name: 'AUDIT Alice Client', exact: true }).check(); const r = await submit('Create booking', '/api/bookings'); await page.waitForURL('**/ticketing/' + r.bookingId); await visible(r.bookingNo); return r; }
async function ticket(number) { await label('Booking status').selectOption('TICKETED'); const d = page.getByRole('dialog', { name: 'Record airline-issued tickets' }); await label('Actual ticket number *', d).fill(number); await label('Ticket fare (INR)', d).fill('1000.10'); await submit('Record & mark ticketed', '/api/bookings/status', d); await d.waitFor({ state: 'hidden' }); await visible(number); }
async function invoice({ work = '', amount = '1000.10', description = 'AUDIT invoice' } = {}) { await go(`/payments?action=invoice&customer=${data.alice.id}`); const d = page.getByRole('dialog'); if (work) await label('02 / Link to work (optional)', d).selectOption(work); await label('03 / Amount (INR) *', d).fill(amount); await label('Description', d).fill(description); await label('Due date', d).fill('2026-10-01'); const r = await submit('Create invoice', '/api/invoices', d); await d.waitFor({ state: 'hidden' }); await visible(r.invoiceNo); return r; }
async function receipt({ allocation = '', amount = '10', mode = 'UPI' } = {}) { await go(`/payments?action=record&customer=${data.alice.id}`); const d = page.getByRole('dialog'); if (allocation) await label('02 / Allocate to', d).selectOption(allocation); await label('03 / Amount (INR) *', d).fill(amount); await select('Received via', mode, d); await label('Reference / note (optional)', d).fill('AUDIT recorded money only'); const r = await submit('Save receipt', '/api/payments', d); await d.waitFor({ state: 'hidden' }); await visible(r.receiptNo); return r; }
async function refund(amount, reason) { await go('/refunds'); await click('Request refund'); const d = page.getByRole('dialog', { name: 'Request refund' }); await label('Booking *', d).selectOption(data.booking.bookingId); await label('Requested amount (INR) *', d).fill(amount); await label('Reason *', d).fill(reason); const r = await submit('Create refund request', '/api/refunds', d); await d.waitFor({ state: 'hidden' }); await visible(r.refund.refundNo); return r.refund; }
async function advanceRefund(id) { for (const stage of ['SUPPLIER PENDING', 'SUPPLIER RECEIVED', 'APPROVED', 'PROCESSED', 'PAID']) { const card = page.locator('div.border.rounded-xl').filter({ hasText: id }).first(); await submit('→ ' + stage, '/api/refunds/update', card); await visible(stage, card); } }
